import assert from 'node:assert/strict';
import sharp from 'sharp';
import { mkdtemp, writeFile, readFile, rm } from 'node:fs/promises';
import { spawn, spawnSync } from 'node:child_process';
import path from 'node:path';
import { once } from 'node:events';
import { DEFAULTS } from './lib/mockup.mjs';

for (const file of ['server.mjs', 'cli.mjs', 'lib/validation.mjs', 'public/app.js']) {
  const check = spawnSync(process.execPath, ['--check', file], { encoding: 'utf8' });
  assert.equal(check.status, 0, check.stderr);
  console.log(`Sintaxis OK: ${file}`);
}
const temp = await mkdtemp(path.join(process.cwd(), '.verificacion-'));
const server = spawn(process.execPath, ['server.mjs'], { stdio: ['ignore', 'pipe', 'pipe'] });
let logs = '';
server.stdout.on('data', chunk => { logs += chunk; });
server.stderr.on('data', chunk => { logs += chunk; });
const base = 'http://127.0.0.1:4173';
try {
  await Promise.race([
    once(server.stdout, 'data'),
    new Promise((_, reject) => setTimeout(() => reject(new Error('El servidor no inicio: ' + logs)), 5000).unref())
  ]);
  assert.match(logs, /127\.0\.0\.1:4173/);
  const rectangle = await sharp({ create: { width: 80, height: 140, channels: 3, background: '#db342a' } }).png().toBuffer();
  const image = await sharp({ create: { width: 240, height: 300, channels: 3, background: 'white' } })
    .composite([{ input: rectangle, left: 80, top: 80 }]).png().toBuffer();
  const background = await sharp({ create: { width: 240, height: 300, channels: 3, background: '#174fad' } }).jpeg().toBuffer();
  await writeFile(path.join(temp, 'prenda.png'), image);
  await writeFile(path.join(temp, 'fondo.jpg'), background);
  await writeFile(path.join(temp, 'rota.png'), 'imagen rota');
  const dataURL = 'data:image/png;base64,' + image.toString('base64');
  const fondoURL = 'data:image/jpeg;base64,' + background.toString('base64');
  const options = { ancho: 240, alto: 300, sombra: false, fondo: '#1c1c1c' };
  const post = body => fetch(base + '/api/generar', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body) });

  const defaultsResponse = await fetch(base + '/api/opciones');
  assert.equal(defaultsResponse.status, 200);
  assert.deepEqual(await defaultsResponse.json(), DEFAULTS);
  console.log('GET /api/opciones: 200, coincide con DEFAULTS');
  for (const [name, fondo, expected] of [['color', null, [28, 28, 28]], ['imagen de fondo', fondoURL, [23, 79, 173]]]) {
    const response = await post({ imagen: dataURL, fondo, opciones: options });
    assert.equal(response.status, 200, await response.clone().text());
    assert.equal(response.headers.get('content-type'), 'image/webp');
    const bytes = Buffer.from(await response.arrayBuffer());
    const metadata = await sharp(bytes).metadata();
    assert.equal(metadata.format, 'webp');
    assert.equal(metadata.width, 240);
    assert.equal(metadata.height, 300);
    const pixel = await sharp(bytes).extract({ left: 0, top: 0, width: 1, height: 1 }).removeAlpha().raw().toBuffer();
    expected.forEach((value, index) => assert.ok(Math.abs(pixel[index] - value) <= 5));
    console.log(`POST /api/generar (${name}): 200, WebP 240x300, fondo verificado`);
  }
  for (const [name, body] of [
    ['rango invalido', { imagen: dataURL, fondo: null, opciones: { escala: 2 } }],
    ['tipo invalido', { imagen: dataURL, fondo: null, opciones: { ancho: '240' } }],
    ['imagen multiple', { imagen: [dataURL], fondo: null, opciones: {} }],
    ['formato prohibido', { imagen: 'data:image/svg+xml;base64,PHN2Zz4=', fondo: null, opciones: {} }],
    ['MIME falsificado', { imagen: 'data:image/webp;base64,' + image.toString('base64'), fondo: null, opciones: {} }],
    ['campo desconocido', { imagen: dataURL, fondo: null, opciones: { archivo: 'secreto' } }],
    ['booleano invalido', { imagen: dataURL, fondo: null, opciones: { quitar_huecos: 0.2 } }],
    ['sombra invalida', { imagen: dataURL, fondo: null, opciones: { sombra: { opacidad: -1 } } }],
  ]) {
    const response = await post(body);
    assert.equal(response.status, 400);
    assert.equal(typeof (await response.json()).error, 'string');
    console.log(`Validacion OK: ${name} (400)`);
  }
  const collage = await sharp({ create: { width: 100, height: 100, channels: 3, background: 'blue' } })
    .composite([{ input: await sharp({ create: { width: 100, height: 50, channels: 3, background: 'red' } }).png().toBuffer(), left: 0, top: 0 }]).png().toBuffer();
  const rejected = await post({ imagen: 'data:image/png;base64,' + collage.toString('base64'), fondo: null, opciones: options });
  assert.equal(rejected.status, 422);
  assert.match((await rejected.json()).error, /fondo liso/);
  console.log('Collage: 422 con mensaje del generador');
  const oversized = await fetch(base + '/api/generar', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: ' '.repeat(25 * 1024 * 1024 + 1) });
  assert.equal(oversized.status, 400);
  assert.match((await oversized.json()).error, /25 MB/);
  console.log('Limite de 25 MB: 400');
  for (const route of ['/', '/app.js', '/styles.css']) {
    assert.equal((await fetch(base + route)).status, 200);
  }
  for (const route of ['/..%2fpackage.json', '/..%5clib%5cmockup.mjs', '/%00']) {
    const response = await fetch(base + route);
    assert.ok([400, 404].includes(response.status));
  }
  console.log('Estaticos: 200; path traversal bloqueado');

  const optionsPath = path.join(temp, 'opciones.json');
  await writeFile(optionsPath, JSON.stringify(options));
  const output = path.join(temp, 'salida');
  const cli = spawnSync(process.execPath, ['cli.mjs', path.join(temp, 'rota.png'), path.join(temp, 'prenda.png'), '--salida', output, '--opciones', optionsPath], { encoding: 'utf8' });
  assert.equal(cli.status, 1);
  assert.match(cli.stdout, /1 OK, 1 error/);
  assert.match(cli.stderr, /ERROR/);
  assert.equal((await sharp(await readFile(path.join(output, 'prenda-mock.webp'))).metadata()).format, 'webp');
  console.log('CLI: continua despues del archivo roto; 1 OK y 1 error; WebP guardada');
  const cliBackground = spawnSync(process.execPath, ['cli.mjs', path.join(temp, 'prenda.png'), '--fondo', path.join(temp, 'fondo.jpg'), '--salida', output, '--opciones', optionsPath], { encoding: 'utf8' });
  assert.equal(cliBackground.status, 0, cliBackground.stderr);
  assert.match(cliBackground.stdout, /1 OK, 0 error/);
  console.log('CLI con --fondo y --opciones: 1 OK, 0 errores');
  const cliFolder = spawnSync(process.execPath, ['cli.mjs', temp, '--color', '#1c1c1c', '--salida', output, '--opciones', optionsPath], { encoding: 'utf8' });
  assert.equal(cliFolder.status, 1);
  assert.match(cliFolder.stdout, /1 OK, 2 error/);
  console.log('CLI con carpeta y --color: prenda OK; fondo sin prenda y archivo roto reportados');
} finally {
  server.kill();
  await once(server, 'exit');
  assert.ok(path.relative(process.cwd(), temp).startsWith('.verificacion-'));
  await rm(temp, { recursive: true, force: true });
  console.log('Servidor cerrado; todos los archivos sinteticos y salidas de prueba eliminados');
}
