Existing graph: False
   1: // Recorta la prenda de un mockup con fondo liso y la compone sobre un fondo nuevo.
   2: // Copia del núcleo de Tienda Street/scripts/mocks/generar.mjs (npm run mocks:generar).
   3: import sharp from 'sharp';
   4: // Ojo: en sharp, erode() agranda las zonas blancas de una máscara y dilate() las achica
   5: // (la morfología de libvips toma el negro como figura). Acá: erode = agrandar, dilate = achicar.
   6: import { readFile } from 'node:fs/promises';
   7: import { createRequire } from 'node:module';
   8: import { dirname, join } from 'node:path';
   9: import { pathToFileURL } from 'node:url';
  10: 
  11: // Modelo local de recorte (modo "preciso"): se carga recién cuando se usa. No redibuja la imagen,
  12: // solo decide qué píxeles son prenda; los colores salen de la foto original.
  13: let removeBackground;
  14: async function modelMask(pngBytes) {
  15:   const name = '@imgly/background-removal-node';
  16:   if (!removeBackground) {
  17:     try {
  18:       ({ removeBackground } = await import(name));
  19:     } catch {
  20:       throw new Error('falta el modelo de recorte preciso: ejecutá npm install en ImageGenerator, o usá el recorte rápido');
  21:     }
  22:   }
  23:   const dist = dirname(createRequire(import.meta.url).resolve(name));
  24:   const blob = await removeBackground(new Blob([pngBytes], { type: 'image/png' }), {
  25:     publicPath: `${pathToFileURL(join(dist, '/')).href}`,
  26:     model: 'medium',
  27:     output: { format: 'image/png' },
  28:   });
  29:   return sharp(Buffer.from(await blob.arrayBuffer())).ensureAlpha().extractChannel(3).raw().toBuffer({ resolveWithObject: true });
  30: }
  31: 
  32: export const DEFAULTS = {
  33:   fondo: '#1c1c1c',
  34:   ancho: 1200,
  35:   alto: 1500,
  36:   escala: 0.78,
  37:   posicion_vertical: 0.5,
  38:   recorte: 'preciso',
  39:   tolerancia: 8,
  40:   recortar_borde: 1,
  41:   rellenar_bordes: 8,
  42:   suavizar_contorno: 3,
  43:   borde_suave: 0.6,
  44:   quitar_huecos: false,
  45:   sombra_original: true,
  46:   sombra: { opacidad: 0.45, desenfoque: 22, x: 0, y: 16 },
  47: };
  48: 
  49: export function merge(...layers) {
  50:   const result = { ...DEFAULTS, sombra: { ...DEFAULTS.sombra } };
  51:   for (const layer of layers.filter(Boolean)) {
  52:     for (const [key, value] of Object.entries(layer)) {
  53:       result[key] = key === 'sombra' && value ? { ...result.sombra, ...value } : value;
  54:     }
  55:   }
  56:   return result;
  57: }
  58: 
  59: 
  60: export async function cutout(bytes, { recorte, tolerancia, recortar_borde, rellenar_bordes, suavizar_contorno, borde_suave, quitar_huecos, sombra_original }) {
  61:   const { data, info } = await sharp(bytes).rotate().ensureAlpha().raw().toBuffer({ resolveWithObject: true });
  62:   const { width, height } = info;
  63:   const original = Buffer.from(data);
  64:   const total = width * height;
  65:   const border = [];
  66:   for (let x = 0; x < width; x++) {
  67:     border.push(x, (height - 1) * width + x);
  68:   }
  69:   for (let y = 1; y < height - 1; y++) {
  70:     border.push(y * width, y * width + width - 1);
  71:   }
  72: 
  73:   const alpha = new Uint8Array(total);
  74:   const transparentBorder = border.filter(i => data[i * 4 + 3] < 250).length;
  75:   if (transparentBorder > border.length / 2) {
  76:     // PNG que ya viene sin fondo.
  77:     for (let i = 0; i < total; i++) {
  78:       alpha[i] = data[i * 4 + 3];
  79:     }
  80:   } else if (recorte === 'preciso') {
  81:     const median = channel => {
  82:       const values = border.map(i => data[i * 4 + channel]).sort((x, y) => x - y);
  83:       return values[values.length >> 1];
  84:     };
  85:     const bg = [median(0), median(1), median(2)];
  86:     // Con fondo claro, el modelo recibe una copia con más contraste: una remera crema sobre blanco
  87:     // casi no se distingue y el modelo se quedaría solo con el estampado. Es solo para la máscara.
  88:     let input = sharp(data, { raw: { width, height, channels: 4 } }).removeAlpha();
  89:     if ((bg[0] + bg[1] + bg[2]) / 3 > 200) {
  90:       input = input.linear(4, -3 * 255);
  91:     }
  92:     const { data: mask, info: maskInfo } = await modelMask(await input.png().toBuffer());
  93:     if (maskInfo.width !== width || maskInfo.height !== height) {
  94:       throw new Error('el modelo devolvió una máscara de otro tamaño');
  95:     }
  96:     // Silueta: lo que el modelo marca con confianza (≥ 50 %) es prenda, incluidos los huecos que deja
  97:     // adentro (con un estampado grande a veces duda en el cuerpo de la remera). En la franja dudosa
  98:     // (contorno con poca confianza) decide el color: lo que es igual al fondo viejo se va.
  99:     const flood = threshold => {
 100:       const outside = new Uint8Array(total);
 101:       const queue = new Int32Array(total);
 102:       let tail = 0;
 103:       for (const i of border) {
 104:         if (mask[i] < threshold && !outside[i]) {
