const b=await stub.cutout(png,{...opts,rellenar_bordes:40,suavizar_contorno:20});
console.log('precise fill/smooth ignored',a.equals(b));
const trim=await stub.cutout(png,{...opts,recortar_borde:2});
console.log('trim changes output',!a.equals(trim));
const missingSource=source.replace(/async function modelMask\(\) \{[^\n]*\}/, 'async function modelMask() { try { await import("@review/nonexistent-model"); } catch { throw new Error("falta el modelo de recorte preciso"); } }');
