let missing=originalSource.replace("import sharp from 'sharp';",`import sharp from '${pathToFileURL(req.resolve('sharp')).href}';`).replace("const name = '@imgly/background-removal-node';","const name = '@review/nonexistent-model';");
const absent=await import('data:text/javascript;base64,'+Buffer.from(missing).toString('base64'));
try {await absent.cutout(png,opts)} catch(e) {console.log('missing package error',e.message)}
const size=1200;
const fragmented=Buffer.alloc(size*size*4,255);
let count=0;
for(let y=1;y<size-1;y+=3) for(let x=1;x<size-1;x+=3) {
 count++;
 const i=(y*size+x)*4;
 fragmented[i]=fragmented[i+1]=fragmented[i+2]=0;
}
const fragmentedPng=await sharp(fragmented,{raw:{width:size,height:size,channels:4}}).png().toBuffer();
try {await cutout(fragmentedPng,merge({recorte:'rapido',sombra_original:false,rellenar_bordes:0,suavizar_contorno:0,recortar_borde:0,borde_suave:0})); console.log('fragmentation passed')} catch(e) {console.log('fragmentation',count,e.name,e.message,e.stack.split('\n')[1])}
